// generated by AI (GitHub Copilot, DeepSeek V4 Flash Vision Exp)
// Transport for the opaque encrypted databases. Talks to the Phase 9 blob and
// discovery routes; no cryptography happens here (the bytes are encrypted).

import axios from '@nextcloud/axios';
import { generateUrl } from '@nextcloud/router';

import type { DatabaseDescriptor, RemoteDatabase } from './descriptor';

/** Raw shape returned by the controller (fileId is numeric there). */
interface RawDatabase {
  fileId: number;
  path: string;
  name: string;
  size: number;
  mtime: number;
  canWrite: boolean;
}

/** Thrown when the file exists but the user may not overwrite it. */
export class ReadOnlyError extends Error {
  constructor() {
    super('The database is read-only.');
    this.name = 'ReadOnlyError';
  }
}

/** The subset of the app config the frontend needs. */
export interface AppConfig {
  userId: string | null;
  defaultFolder: string;
  defaultDatabase: RemoteDatabase | null;
}

function toRemote(raw: RawDatabase): RemoteDatabase {
  return {
    id: String(raw.fileId),
    path: raw.path,
    name: raw.name,
    size: raw.size,
    mtime: raw.mtime,
    canWrite: raw.canWrite,
  };
}

function databaseUrl(id: string): string {
  return generateUrl(`/apps/upm/databases/${encodeURIComponent(id)}`);
}

function httpStatus(error: unknown): number | undefined {
  return (error as { response?: { status?: number } })?.response?.status;
}

/** Read the app config (default folder and, when present, the default DB). */
export async function getConfig(): Promise<AppConfig> {
  const response = await axios.get(generateUrl('/apps/upm/config'));
  const data = response.data as {
    userId: string | null;
    defaultFolder: string;
    defaultDatabase: RawDatabase | null;
  };
  return {
    userId: data.userId,
    defaultFolder: data.defaultFolder,
    defaultDatabase: data.defaultDatabase ? toRemote(data.defaultDatabase) : null,
  };
}

/** List the `*.db` files in the configured root folder. */
export async function listDatabases(): Promise<RemoteDatabase[]> {
  const response = await axios.get(generateUrl('/apps/upm/databases'));
  return (response.data as RawDatabase[]).map(toRemote);
}

/** Describe one database by its user-relative path, or null when missing. */
export async function lookupDatabase(path: string): Promise<RemoteDatabase | null> {
  const response = await axios.get(generateUrl('/apps/upm/databases/lookup'), {
    params: { path },
    validateStatus: (status) => status === 200 || status === 404,
  });
  return response.status === 404 ? null : toRemote(response.data as RawDatabase);
}

/** Download the encrypted database, or `null` when it does not exist. */
export async function getDb(descriptor: DatabaseDescriptor): Promise<Uint8Array | null> {
  if (descriptor.id === '') {
    return null;
  }
  const response = await axios.get(databaseUrl(descriptor.id), {
    responseType: 'arraybuffer',
    validateStatus: (status) => status === 200 || status === 404,
  });
  if (response.status === 404) {
    return null;
  }
  return new Uint8Array(response.data as ArrayBuffer);
}

/** Upload the encrypted database as raw bytes. */
export async function putDb(
  descriptor: DatabaseDescriptor,
  bytes: Uint8Array,
): Promise<void> {
  try {
    await axios.put(databaseUrl(descriptor.id), bytes, {
      headers: { 'Content-Type': 'application/octet-stream' },
    });
  } catch (error) {
    if (httpStatus(error) === 403) {
      throw new ReadOnlyError();
    }
    throw error;
  }
}

/** Create a new database file at `path` and return its descriptor. */
export async function createDatabase(path: string, bytes: Uint8Array): Promise<RemoteDatabase> {
  const response = await axios.post(generateUrl('/apps/upm/databases'), bytes, {
    params: { path },
    headers: { 'Content-Type': 'application/octet-stream' },
  });
  return toRemote(response.data as RawDatabase);
}

/**
 * Persist bytes for a descriptor: create the file on first save (id === ''),
 * otherwise overwrite it. Returns the descriptor with a real id.
 */
export async function saveDatabase(
  descriptor: DatabaseDescriptor,
  bytes: Uint8Array,
): Promise<DatabaseDescriptor> {
  if (descriptor.id === '') {
    const created = await createDatabase(descriptor.path, bytes);
    return {
      id: created.id,
      label: descriptor.label,
      path: created.path,
      canWrite: created.canWrite,
    };
  }
  await putDb(descriptor, bytes);
  return descriptor;
}

/** Delete the stored database (a missing file counts as success). */
export async function deleteDb(descriptor: DatabaseDescriptor): Promise<void> {
  if (descriptor.id === '') {
    return;
  }
  await axios.delete(databaseUrl(descriptor.id));
}
